import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Native Agent Runtime","description":"How Hearth uses a Pi-style single-agent tool loop with task-scoped permissions, budgets, checkpoints, and recovery.","frontmatter":{"title":"Native Agent Runtime","description":"How Hearth uses a Pi-style single-agent tool loop with task-scoped permissions, budgets, checkpoints, and recovery.","outline":[2,3]},"headers":[],"relativePath":"en/design/native-agent-runtime.md","filePath":"en/design/native-agent-runtime.md","lastUpdated":1793970107000}'),o={name:"en/design/native-agent-runtime.md"};function i(r,e,l,d,p,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="native-agent-runtime" tabindex="-1">Native Agent Runtime <a class="header-anchor" href="#native-agent-runtime" aria-label="Permalink to &quot;Native Agent Runtime&quot;">​</a></h1><p class="lead">Hearth&#39;s native executor is not a prompt that forwards a task to a model. It is a single-agent tool loop that can pause, resume, and enforce permissions and budgets. It follows the shape of Pi&#39;s compact kernel but is implemented by Hearth and does not depend on the Pi npm package.</p><h2 id="two-execution-paths" tabindex="-1">Two execution paths <a class="header-anchor" href="#two-execution-paths" aria-label="Permalink to &quot;Two execution paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Executor</th><th>Role</th><th>Typical work</th></tr></thead><tbody><tr><td><code>native</code></td><td>General single agent using the configured chat model and built-in tools</td><td>Research notes, documents, web summaries, simple file work</td></tr><tr><td><code>codex</code></td><td>Specialist for repositories and multi-file engineering</td><td>Code fixes, tests, commits, workspace changes</td></tr></tbody></table><p>The native executor is the default general path. The router selects Codex only for explicit repository or engineering work. A failed task does not silently switch executors.</p><h2 id="kernel-shape" tabindex="-1">Kernel shape <a class="header-anchor" href="#kernel-shape" aria-label="Permalink to &quot;Kernel shape&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task + user follow-up</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>system prompt + message history</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>streamed model turn ──→ answer / tool calls</span></span>
<span class="line"><span>        ↓                       ↓</span></span>
<span class="line"><span>usage and budget         permissioned tools</span></span>
<span class="line"><span>        ↓                       ↓</span></span>
<span class="line"><span>checkpoint  ←────────  tool result is appended</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>completed / waiting input / budget exceeded / cancelled</span></span></code></pre></div><p>The model must call <code>finish_task</code> to declare completion, and declared outputs must exist and be non-empty. The runtime, not the model&#39;s prose, decides whether a task is complete.</p><h2 id="protocols-and-tools" tabindex="-1">Protocols and tools <a class="header-anchor" href="#protocols-and-tools" aria-label="Permalink to &quot;Protocols and tools&quot;">​</a></h2><p>Hearth supports OpenAI Chat Completions, OpenAI Responses, Anthropic Messages, and Gemini through one normalized streaming agent turn. Provider changes do not alter the tool loop.</p><p>Built-in tools cover reading, listing, searching, writing, editing, patching, shell checks, URL fetches, user questions, and completion. Paths are restricted to the task workspace and output directory, network access is deny-by-default, and shell is enabled only for workspace tasks. Dangerous commands, symlink escapes, private addresses, and unapproved hosts are rejected at the tool layer.</p><h2 id="budgets-checkpoints-and-recovery" tabindex="-1">Budgets, checkpoints, and recovery <a class="header-anchor" href="#budgets-checkpoints-and-recovery" aria-label="Permalink to &quot;Budgets, checkpoints, and recovery&quot;">​</a></h2><p>Runs enforce limits on turns, tool calls, tokens, and duration. Checkpoints are written after model turns, tool steps, waiting-input pauses, and completion. Recovery copies the prior workspace, restores messages and counters, appends a user follow-up when present, and continues from the pause instead of restarting.</p><p>When declared deliverables are missing, the runtime sends a repair prompt with the previous agent context and allows up to two repair rounds. If the contract still fails, the task fails explicitly.</p><h2 id="completion-contract" tabindex="-1">Completion contract <a class="header-anchor" href="#completion-contract" aria-label="Permalink to &quot;Completion contract&quot;">​</a></h2><ul><li>General and delivery tasks must produce their declared outputs, normally <code>result.md</code>.</li><li>Workspace tasks must include a final summary plus evidence of changes and tests.</li><li>Intermediate JSON, command logs, checkpoints, and runtime files are never user deliverables.</li><li>A task detail shows the final result and declared files first; commands and checkpoints remain folded technical details.</li></ul><h2 id="proposals-and-approval" tabindex="-1">Proposals and approval <a class="header-anchor" href="#proposals-and-approval" aria-label="Permalink to &quot;Proposals and approval&quot;">​</a></h2><p>Tasks that need network access or engineering workspace writes create a proposal in chat before dispatch. The proposal states the executor, expected outputs, requested hosts, and reason. The task is created only after the user confirms; rejecting it creates nothing. Ordinary general tasks can be dispatched directly.</p><h2 id="current-boundaries" tabindex="-1">Current boundaries <a class="header-anchor" href="#current-boundaries" aria-label="Permalink to &quot;Current boundaries&quot;">​</a></h2><ul><li>One agent per task; no parallel subagents in this version.</li><li>Execution uses the configured chat model; there is no hidden second execution model.</li><li>Network is denied by default and workspaces are isolated per run.</li><li>Pi is a design reference, not an integrated runtime dependency.</li></ul>`,20)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
